3	namespace App\Jobs\Shopify;
4	
5	use App\Models\Core\Professional\Professional;
6	use App\Models\Retail\CommissionLedgerEntry;
7	use App\Services\Notifications\NotificationPublisher;
8	use Illuminate\Bus\Queueable;
9	use Illuminate\Contracts\Queue\ShouldQueue;
10	use Illuminate\Foundation\Bus\Dispatchable;
11	use Illuminate\Queue\InteractsWithQueue;
12	use Illuminate\Queue\SerializesModels;
13	use Illuminate\Support\Arr;
14	use Illuminate\Support\Facades\DB;
15	use Illuminate\Support\Facades\Log;
16	
17	// V2: Processes orders/updated webhooks — handles full refunds, partial refunds, and cancellations by reversing commission ledger entries.
18	class ProcessShopifyOrderUpdatedWebhookJob implements ShouldQueue
19	{
20	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
21	
22	    public int $tries = 3;
23	
24	    public int $timeout = 30;
25	
26	    public function __construct(
27	        public string $professionalId,
28	        public array $payload,
29	    ) {
30	        $this->onQueue('integrations');
31	    }
32	
33	    public function handle(): void
34	    {
35	        if (! Professional::find($this->professionalId)) {
36	            Log::warning('ProcessShopifyOrderUpdatedWebhookJob: brand professional not found, skipping', [
37	                'professional_id' => $this->professionalId,
38	            ]);
39	
40	            return;
41	        }
42	
43	        $orderId = (string) Arr::get($this->payload, 'id', '');
44	        $financialStatus = strtolower(trim((string) Arr::get($this->payload, 'financial_status', '')));
45	
46	        if ($orderId === '' || $financialStatus === '') {
47	            return;
48	        }
49	
50	        // Only act on refund/cancel statuses
51	        if (! in_array($financialStatus, ['refunded', 'voided', 'partially_refunded'], true)) {
52	            return;
53	        }
54	
55	        // Find existing accrual entries for this order
56	        $accruals = CommissionLedgerEntry::query()
57	            ->where('shopify_order_id', $orderId)
58	            ->where('entry_type', 'accrual')
59	            ->get();
60	
61	        if ($accruals->isEmpty()) {
62	            return;
63	        }
64	
65	        if ($financialStatus === 'partially_refunded') {
66	            $this->handlePartialRefund($orderId, $accruals);
67	        } else {
68	            $this->handleFullRefund($orderId, $accruals);
69	        }
70	
71	        // Rebuild commerce daily aggregates so refunded_cents and commission_reversed_cents
72	        // are reflected in dashboards and weekly notifications.
73	        $this->dispatchCommerceRebuilds($accruals);
74	    }
75	
76	    private function handleFullRefund(string $orderId, $accruals): void
77	    {
78	        $reversed = CommissionLedgerEntry::query()
79	            ->where('shopify_order_id', $orderId)
80	            ->where('entry_type', 'accrual')
81	            ->where('status', 'approved')
82	            ->update(['status' => 'reversed', 'updated_at' => now()]);
83	
84	        if ($reversed > 0) {
85	            $this->notifyAffiliatesOfRefund($orderId, $accruals, fullRefund: true);
86	        }
87	
88	        Log::info('Shopify order fully refunded/cancelled — commissions reversed.', [
89	            'professional_id' => $this->professionalId,
90	            'order_id' => $orderId,
91	            'entries_reversed' => $reversed,
92	        ]);
93	    }
94	
95	    private function handlePartialRefund(string $orderId, $accruals): void
96	    {
97	        $refunds = Arr::get($this->payload, 'refunds', []);
98	
99	        if (! is_array($refunds)) {
100	            return;
101	        }
102	
103	        // Index accruals by line_item_id for fast lookup
104	        $accrualsByLineItem = [];
105	        foreach ($accruals as $accrual) {
106	            $meta = is_array($accrual->calculation_metadata) ? $accrual->calculation_metadata : [];
107	            $lineItemId = (string) ($meta['line_item_id'] ?? '');
108	            if ($lineItemId !== '') {
109	                $accrualsByLineItem[$lineItemId] = $accrual;
110	            }
111	        }
112	
113	        // Phase 1: flatten nested refund loops into candidates without touching the DB
114	        $candidates = [];
115	        foreach ($refunds as $refund) {
116	            if (! is_array($refund)) {
117	                continue;
118	            }
119	
120	            $refundId = (string) Arr::get($refund, 'id', '');
121	            $refundLineItems = Arr::get($refund, 'refund_line_items', []);
122	
123	            if ($refundId === '' || ! is_array($refundLineItems)) {
124	                continue;
125	            }
126	
127	            foreach ($refundLineItems as $refundLine) {
128	                if (! is_array($refundLine)) {
129	                    continue;
130	                }
131	
132	                $lineItemId = (string) Arr::get($refundLine, 'line_item_id', '');
133	                $refundSubtotal = (float) Arr::get($refundLine, 'subtotal', 0);
134	
135	                if ($lineItemId === '' || $refundSubtotal <= 0) {
136	                    continue;
137	                }
138	
139	                $originalAccrual = $accrualsByLineItem[$lineItemId] ?? null;
140	
141	                if (! $originalAccrual || $originalAccrual->status !== 'approved') {
142	                    continue;
143	                }
144	
145	                $commissionRate = (float) $originalAccrual->commission_rate;
146	                $reversalCents = (int) round($refundSubtotal * ($commissionRate / 100) * 100);
147	
148	                if ($reversalCents <= 0) {
149	                    continue;
150	                }
151	
152	                $candidates[] = [
153	                    'idempotency_key' => "shopify_order_{$orderId}_refund_{$refundId}_line_{$lineItemId}",
154	                    'data' => [
155	                        'shopify_order_id' => $orderId,
156	                        'brand_professional_id' => (string) $originalAccrual->brand_professional_id,
157	                        'affiliate_professional_id' => (string) $originalAccrual->affiliate_professional_id,
158	                        'entry_type' => 'reversal',
159	                        'status' => 'approved',
160	                        'amount_cents' => -$reversalCents,
161	                        'currency_code' => $originalAccrual->currency_code,
162	                        'commission_rate' => $commissionRate,
163	                        'rate_source' => 'refund',
164	                        'idempotency_key' => "shopify_order_{$orderId}_refund_{$refundId}_line_{$lineItemId}",
165	                        'calculation_metadata' => [
166	                            'order_id' => $orderId,
167	                            'refund_id' => $refundId,
168	                            'line_item_id' => $lineItemId,
169	                            'refund_subtotal' => $refundSubtotal,
170	                            'original_accrual_id' => (string) $originalAccrual->id,
171	                        ],
172	                        'occurred_at' => now(),
173	                    ],
174	                ];
175	            }
176	        }
177	
178	        // Phase 2: pre-filter duplicates in one query, then insert in one transaction.
179	        $reversalsCreated = 0;
180	        if (! empty($candidates)) {
181	            $candidateKeys = array_column($candidates, 'idempotency_key');
182	            $existingKeys = CommissionLedgerEntry::whereIn('idempotency_key', $candidateKeys)
183	                ->pluck('idempotency_key')
184	                ->flip()
185	                ->all();
186	
187	            $newEntries = array_filter($candidates, fn ($c) => ! isset($existingKeys[$c['idempotency_key']]));
188	
189	            // Pre-fetch affiliates so the observer's notifyBrandSale() doesn't lazy-load
190	            // affiliateProfessional for each reversal entry (N+1 on display_name).
191	            // setRelation pre-sets below survive the observer's afterCommit dispatch —
192	            // Laravel keeps object identity (no clone) for synchronous post-commit callbacks.
193	            $affiliateIds = collect($newEntries)
194	                ->pluck('data.affiliate_professional_id')
195	                ->filter()
196	                ->unique()
197	                ->values()
198	                ->all();
199	
200	            $affiliatesById = Professional::query()
201	                ->whereIn('id', $affiliateIds)
202	                ->get(['id', 'display_name'])
203	                ->keyBy('id');
204	
205	            DB::transaction(function () use ($newEntries, $affiliatesById, &$reversalsCreated): void {
206	                foreach ($newEntries as $entry) {
207	                    $row = (new CommissionLedgerEntry)->forceFill($entry['data']);
208	                    $affiliate = $affiliatesById->get($entry['data']['affiliate_professional_id'] ?? null);
209	                    if ($affiliate) {
210	                        $row->setRelation('affiliateProfessional', $affiliate);
211	                    }
212	                    $row->save();
213	                    $reversalsCreated++;
214	                }
215	            });
216	        }
217	
218	        if ($reversalsCreated > 0) {
219	            $this->notifyAffiliatesOfRefund($orderId, $accruals, fullRefund: false);
220	        }
221	
222	        Log::info('Shopify order partially refunded — reversal entries created.', [
223	            'professional_id' => $this->professionalId,
224	            'order_id' => $orderId,
225	            'reversals_created' => $reversalsCreated,
226	        ]);
227	    }
228	
229	    private function dispatchCommerceRebuilds($accruals): void
230	    {
231	        $pairs = $accruals
232	            ->groupBy(fn ($e) => $e->brand_professional_id.'|'.$e->affiliate_professional_id);
233	
234	        foreach ($pairs as $entries) {
235	            $entry = $entries->first();
236	
237	            if (! $entry->occurred_at) {
238	                continue;
239	            }
240	
241	            \App\Jobs\Analytics\RebuildCommerceDailyAggregatesJob::dispatch(
242	                (string) $entry->brand_professional_id,
243	                (string) $entry->affiliate_professional_id,
244	                $entry->occurred_at->toDateString()
245	            );
246	            \App\Jobs\Analytics\RebuildCommerceHourlyAggregatesJob::dispatch(
247	                (string) $entry->brand_professional_id,
248	                (string) $entry->affiliate_professional_id,
249	                $entry->occurred_at->utc()->startOfHour()->toIso8601String()
250	            );
251	        }
252	    }
253	
254	    private function notifyAffiliatesOfRefund(string $orderId, $accruals, bool $fullRefund): void
255	    {
256	        $publisher = app(NotificationPublisher::class);
257	
258	        $affiliateIds = $accruals
259	            ->pluck('affiliate_professional_id')
260	            ->filter()
261	            ->unique()
262	            ->values();
263	
264	        foreach ($affiliateIds as $affiliateId) {
265	            $affiliateAccruals = $accruals->where('affiliate_professional_id', $affiliateId);
266	            $totalCents = $affiliateAccruals->sum('amount_cents');
267	            $currency = $affiliateAccruals->first()->currency_code ?? 'AUD';
268	            $formatted = strtoupper($currency).' $'.number_format($totalCents / 100, 2);
269	
270	            $body = $fullRefund
271	                ? "A sale was refunded — your {$formatted} commission has been cancelled."
272	                : 'A sale was partially refunded — your commission has been adjusted.';
273	
274	            $publisher->publish(
275	                professionalId: (string) $affiliateId,
276	                frontendType: 'Warning',
277	                category: 'commissions',
278	                title: 'Commission '.($fullRefund ? 'cancelled' : 'adjusted'),
279	                body: $body,
280	                dedupeKey: "refund.order.{$orderId}.affiliate.{$affiliateId}",
281	                ctaUrl: '/account/commissions',
282	                primaryActionLabel: 'View Commissions',
283	            );
284	        }
285	    }
286	}
